#!/usr/bin/env node
'use strict';
// Six-native-axis labelled Boolean-BRC vacancy support exact checker.
// Usage: node x6_vacancy_lens_brc_verify_r18.js
function verifyLens() {
 const dim=6, maxR=7, zero=Array(dim).fill(0);
 const key=a=>a.join(",");
 const unit=i=>Array.from({length:dim},(_,j)=>i===j?1:0);
 const add=(a,b)=>a.map((x,i)=>x+b[i]);
 const mul=(a,s)=>a.map(x=>x*s);
 const ball=(radius,center)=>{
  const arr=[],d=Array(dim).fill(0);
  function rec(j,left){if(j===dim){arr.push(add(d,center));return;} for(let t=-left;t<=left;t++){d[j]=t;rec(j+1,left-Math.abs(t));}}
  rec(0,radius);return arr;
 };
 const C=(n,k)=>{let a=1;for(let j=1;j<=k;j++)a=a*(n-j+1)/j;return Math.round(a)};
 const N=(d,r)=>{let sum=0;for(let j=0;j<=Math.min(d,r);j++)sum+=Math.pow(2,j)*C(d,j)*C(r,j);return sum;};
 const directions=[];for(let j=0;j<dim;j++)for(const t of [-1,1])directions.push(mul(unit(j),t));
 function makeStates(S,a,b){
  const places=[new Map(),new Map()];
  for(const x of S.values()){const k=key(x),lab=k===key(a)?"A":k===key(b)?"B":"c:"+k;places[0].set(lab,x);places[1].set(lab==="A"?"B":lab==="B"?"A":lab,x);}
  return places.map(m=>({loc:m,occ:new Set([...m.values()].map(key))}));
 }
 function legal(st,lab,step){const p=st.loc.get(lab);if(!p)throw Error("source missing "+lab);return !st.occ.has(key(add(p,step)));}
 function move(st,lab,step){if(!legal(st,lab,step))return false;const p=st.loc.get(lab),q=add(p,step);st.occ.delete(key(p));st.occ.add(key(q));st.loc.set(lab,q);return true;}
 const results=[];
 for(let r=1;r<=maxR;r++){
  const a=zero,b=unit(0), all=new Map();
  for(const x of ball(r,a))all.set(key(x),x);
  for(const x of ball(r,b))all.set(key(x),x);
  if(all.size!==N(dim,r)+N(dim-1,r))throw Error("population mismatch r="+r);
  if(all.has(key(mul(unit(0),-(r+1)))) || all.has(key(mul(unit(0),r+2))))throw Error("no exterior");
  const states=makeStates(all,a,b);
  let firstLegalSame=true, firstLegalCount=0;
  if(r===1){
   for(const label of states[0].loc.keys())for(const step of directions){
     const l=legal(states[0],label,step),m=legal(states[1],label,step);
     firstLegalCount+=Number(l);if(l!==m)firstLegalSame=false;
   }
   if(!firstLegalSame)throw Error("r1 L1 differs");
  }
  const path=[];
  for(let j=r+1;j>=2;j--)path.push(["c:"+key(mul(unit(0),j)),unit(0)]);
  path.push(["B",unit(0)]);
  let accepted=[true,true],prefix=[true,true];
  for(let j=0;j<path.length;j++)for(let s=0;s<2;s++){
     const works=move(states[s],path[j][0],path[j][1]);
     accepted[s]=accepted[s]&&works;if(j<r)prefix[s]=prefix[s]&&works;
  }
  if(!prefix[0]||!prefix[1]||!accepted[0]||accepted[1])throw Error("witness failure r="+r);
  results.push({r,distinguishing_depth:r+1,full_six_dim_population:all.size,former_ball_population:N(dim,r+1),saved_sources:N(dim,r+1)-all.size,verified_common_prefix:r,final_event_P_legal:true,final_event_Q_legal:false,checked_L1_all_signed_events:r===1?{equal:firstLegalSame,legal_count:firstLegalCount}:null});
 }
 const bar=new Map();for(let j=0;j<4;j++){const u=mul(unit(0),j);bar.set(key(u),u);}
 const states=makeStates(bar,unit(0),mul(unit(0),2));
 for(const lab of states[0].loc.keys())for(const step of directions)if(legal(states[0],lab,step)!==legal(states[1],lab,step))throw Error("bar L1 not equal");
 if(!move(states[0],"A",unit(1))||!move(states[1],"A",unit(1)))throw Error("bar first");
 if(!move(states[0],"c:"+key(zero),unit(0)))throw Error("bar P fail");
 if(move(states[1],"c:"+key(zero),unit(0)))throw Error("bar Q legal");
 return {schema:"X6_LENS_VACANCY_BRC_RESULT_V1",status:"PASS",six_signed_directions:12,case_r_min:1,case_r_max:maxR,model:"labelled nearest-neighbour vacancy moves on chart-relative Z^6, Boolean ordered source/Port support",formula_population:"N6(r)+N5(r)",formula_Nd:"sum(j=0..min(d,r), 2^j*C(d,j)*C(r,j))",cases:results,strict_same_depth_witness:{population:4,distances:[1,1],L1_equal:true,L2_differs:true},universal_proof_status:"mathematical proof in companion MD; checks are finite"};
}
console.log(JSON.stringify(verifyLens(), null, 2));

